/// <reference path="../pb_data/types.d.ts" />

// Per-IP rate limiter for user signup endpoint.
// Limits POST /api/collections/users/records to 3 requests per 60 seconds per IP.
// On the 4th request within the window, returns 429 with Retry-After header and retryAfter body field.

const RATE_LIMIT_WINDOW_MS = 60 * 1000;   // 60 seconds
const RATE_LIMIT_MAX = 3;                  // 3 requests allowed per window

// In-memory map: IP -> array of request timestamps (ms)
const rateLimitStore = {};

function getClientIp(e) {
    // Prefer realIP() since it considers trusted proxy headers; fall back to remoteIP().
    try {
        const ip = e.realIP();
        if (ip) {
            return ip;
        }
    } catch (_) {}
    try {
        return e.remoteIP();
    } catch (_) {
        return "unknown";
    }
}

function pruneOldEntries(timestamps, now) {
    const cutoff = now - RATE_LIMIT_WINDOW_MS;
    // Remove entries older than the rolling window
    let i = 0;
    while (i < timestamps.length && timestamps[i] <= cutoff) {
        i++;
    }
    if (i > 0) {
        timestamps.splice(0, i);
    }
}

onRecordCreateRequest((e) => {
    // Only apply to the built-in users auth collection
    if (e.collection.name !== "users") {
        return;
    }

    const ip = getClientIp(e);
    const now = Date.now();

    let timestamps = rateLimitStore[ip];
    if (!timestamps) {
        timestamps = [];
        rateLimitStore[ip] = timestamps;
    }

    // Drop timestamps that fall outside the current rolling window
    pruneOldEntries(timestamps, now);

    if (timestamps.length >= RATE_LIMIT_MAX) {
        // Compute when the oldest entry will fall out of the window
        const oldest = timestamps[0];
        const retryAfterMs = (oldest + RATE_LIMIT_WINDOW_MS) - now;
        let retryAfterSec = Math.ceil(retryAfterMs / 1000);
        if (retryAfterSec < 1) {
            retryAfterSec = 1;
        }

        // Set the Retry-After header on the response
        try {
            e.response.header().set("Retry-After", String(retryAfterSec));
